<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class CommercialDocument extends Model{protected $guarded=['id'];protected $casts=['document_date'=>'date','valid_until'=>'date','approved_at'=>'datetime','cancelled_at'=>'datetime'];public function lines(){return $this->hasMany(CommercialDocumentLine::class);}public function customer(){return $this->belongsTo(\App\Modules\SafetyShop\Sales\Models\Customer::class);}public function quotation(){return $this->belongsTo(self::class,'quotation_id');}public function revisionOf(){return $this->belongsTo(self::class,'revision_of_id');}public function revisions(){return $this->hasMany(self::class,'revision_of_id');}public function supersededBy(){return $this->belongsTo(self::class,'superseded_by_id');}public function creator(){return $this->belongsTo(User::class,'created_by');}public function approver(){return $this->belongsTo(User::class,'approved_by');}public function canceller(){return $this->belongsTo(User::class,'cancelled_by');}public function sales(){return $this->hasMany(\App\Modules\SafetyShop\Sales\Models\Sale::class,'quotation_id');}public function getLifecycleStatusAttribute(){return $this->superseded_by_id?'superseded':$this->status;}}
